class Program {
 static Assembly mod;static object Call(string type,string method,params object[] args)=>mod.GetTypes().Single(t=>t.Name==type).GetMethods(BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic).Single(m=>m.Name==method&&m.GetParameters().Length==args.Length).Invoke(null,args);
 static void Main(string[] args){string root=Path.GetFullPath(args[0]);AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>{foreach(string folder in new[]{root,Path.GetFullPath(Path.Combine(root,"../../7DaysToDie_Data/Managed")),Path.GetFullPath(Path.Combine(root,"../0_TFP_Harmony"))}){string p=Path.Combine(folder,new AssemblyName(e.Name).Name+".dll");if(File.Exists(p))return Assembly.LoadFrom(p);}return null;};mod=Assembly.LoadFrom(Path.Combine(root,"RebirthUtils.dll"));Call("RebirthSurvivorDefinitionLoader","SetPreferredModRoot",root);var bundle=Call("RebirthSurvivorDefinitionLoader","Load",Path.Combine(root,"Config/_Survivor"));Call("RebirthSurvivorDefinitionRegistry","Install",bundle);Console.WriteLine(Call("RebirthProgressionRuntimeConfig","Load"));Call("RebirthBackgroundBonusRegistry","Install",Path.Combine(root,"Config/_Survivor"));var policy=Call("RebirthRecipeDiscoveryPolicy","Read",XElement.Load(Path.Combine(root,"Config/_CraftingDiscovery/recipe_policy.xml")));int recipes=0;foreach(var r in XDocument.Load(Path.Combine(root,"Config/_CraftingDiscovery/recipe_policy.xml")).Root.Elements("recipe")){string id=(string)r.Attribute("name");object[] capArgs={id,null};if(!(bool)Call("RebirthCapabilityRegistry","TryGetRecipe",capArgs))throw new Exception("Missing capability "+id);var req=capArgs[1].GetType().GetProperty("Requirement").GetValue(capArgs[1]);bool hasMinimum=false;foreach(var child in (IEnumerable)req.GetType().GetProperty("Children").GetValue(req)){if((string)child.GetType().GetProperty("Kind").GetValue(child)=="skill"&&(bool)child.GetType().GetProperty("HasMinimum").GetValue(child))hasMinimum=true;}if(!hasMinimum)throw new Exception("No enforced minimum "+id);var allows=policy.GetType().GetMethod("Allows");if((bool)allows.Invoke(policy,new object[]{id,new Func<string,bool>(_=>false)}))throw new Exception("Unread allowed "+id);if(!(bool)allows.Invoke(policy,new object[]{id,new Func<string,bool>(_=>true)}))throw new Exception("Read rejected "+id);recipes++;}Console.WriteLine("PASS "+recipes+" recipes have actual loaded minimums and reject unread/accept read knowledge");string result=(string)Call("RebirthBackpackExpansionVectorHarness","Run");Console.WriteLine(result);if(!result.StartsWith("PASS"))throw new Exception("backpack regression failed");Call("RebirthProgressionGraphRegistry","Clear");Call("RebirthProgressionGraphRegistry","AddLiteratureSources",bundle);object axeNode=null;bool found=false;foreach(var node in (Array)Call("RebirthProgressionGraphRegistry","GetNodesSnapshot")){var t=node.GetType();if((string)t.GetProperty("Id").GetValue(node)=="literature.read.rebirthTheoryAxesPrimer"){found=true;axeNode=node;}}if(!found)throw new Exception("Axe Handling study node missing");Console.WriteLine("PASS Axe Handling study completion node is present in actual compiled graph");var nt=mod.GetType("RebirthProgressionGraphNode");var et=mod.GetType("RebirthProgressionGraphEdge");var nodes=Array.CreateInstance(nt,1);nodes.SetValue(axeNode,0);var edges=Array.CreateInstance(et,0);var neighborhood=Activator.CreateInstance(mod.GetType("RebirthProgressionGraphNeighborhood"),new object[]{"literature.read.rebirthTheoryAxesPrimer",nodes,edges,false});var vt=mod.GetType("RebirthProgressionOverlayValues");var values=Activator.CreateInstance(vt,true);vt.GetField("Mode").SetValue(values,Enum.Parse(mod.GetType("RebirthProgressionExplorerMode"),"LiveCharacter"));vt.GetField("HasCharacterState").SetValue(values,true);var before=Call("RebirthProgressionExplorerOverlayService","Build",neighborhood,values);object[] lookup={"literature.read.rebirthTheoryAxesPrimer",null};before.GetType().GetMethod("TryGet").Invoke(before,lookup);if((bool)lookup[1].GetType().GetProperty("IsLearnedKnowledge").GetValue(lookup[1]))throw new Exception("Unread marker displayed as learned");var knowledge=vt.GetField("KnowledgeIds").GetValue(values);knowledge.GetType().GetMethod("Add").Invoke(knowledge,new object[]{"literature.read.rebirthTheoryAxesPrimer"});var after=Call("RebirthProgressionExplorerOverlayService","Build",neighborhood,values);lookup[1]=null;after.GetType().GetMethod("TryGet").Invoke(after,lookup);if(!(bool)lookup[1].GetType().GetProperty("IsLearnedKnowledge").GetValue(lookup[1]))throw new Exception("Completed marker not displayed learned");Console.WriteLine("PASS actual Explorer overlay distinguishes unread and completed Axe Handling");foreach(string name in new[]{"EntityRebirthGearRecoveryBackpack","EntityRebirthGearRecoveryItem"})if((bool)Call("RebirthNpcAuthoringValidator","IsRebirthNpcClass",mod.GetType(name)))throw new Exception("Recovery object incorrectly classified NPC");if(!(bool)Call("RebirthNpcAuthoringValidator","IsRebirthNpcClass",mod.GetTypes().Single(t=>t.Name=="EntityRebirthSurvivor")))throw new Exception("Real NPC excluded");Console.WriteLine("PASS recovery objects excluded from NPC authoring; real survivor remains included");var chicken=mod.GetType("ItemClassWildChickenRebirth");if(!chicken.GetCustomAttributesData().Any(a=>a.AttributeType.FullName=="UnityEngine.Scripting.PreserveAttribute"))throw new Exception("Chicken item not preserved");if(chicken.BaseType.Name!="ItemClassWildChicken")throw new Exception("Native chicken behavior not inherited");Console.WriteLine("PASS XML-created chicken class is preserved and inherits native behavior");}
